def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge intervals in a
    a_sorted = sorted(a)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Merge intervals in b
    b_sorted = sorted(b)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and start <= b_merged[-1][1]:
            b_merged[-1][1] = max(b_merged[-1][1], end)
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_current = []
            for c_start, c_end in current:
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    new_current.append([c_start, c_end])
                else:
                    # There is overlap
                    if c_start < b_start:
                        new_current.append([c_start, b_start])
                    if c_end > b_end:
                        new_current.append([b_end, c_end])
            current = new_current

        result.extend(current)

    # Merge touching intervals
    if not result:
        return []

    result_sorted = sorted(result)
    merged_result = [result_sorted[0]]
    for start, end in result_sorted[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

